	public static int findLargePrime(int[] arr){
		int maxp = Integer.MIN_VALUE;
		for(int i = 0; i < arr.length;i++){
			if(arr[i] > maxp && isPrime(arr[i])){
				maxp = arr[i];
			}
		}
		return maxp;
	}

	public static boolean isPrime(int n){

		int den = 2;
		while(den * den <= n){
			if(n % den == 0) return false;
			den++;
		}
		return true;

	}
}




