public class Main {
    public static void main(String[] args) {
        Scanner scan=new Scanner(System.in);
        int n=scan.nextInt();
        Course[] courses=new Course[n];
        for(int i=0;i<n;i++){
            int courseId=scan.nextInt();
            scan.nextLine();
            String courseName=scan.nextLine();
            String courseAdmin=scan.nextLine();
