    public static RRT getHighestPriorityTicket(RRT[]rt, String p)
    {
        RRT[] r = new RRT[0];
        for (int i = 0; i < rt.length; i++) {
            if(rt[i].getProject().equalsIgnoreCase(p))
            {
                r = Arrays.copyOf(r,r.length+1);
                r[r.length-1]=rt[i];
            }
