    {
        double sum = 0;
        int c=0;
        for (int i = 0; i < s.length; i++) {
            sum += s[i].getGpa();
            c++;
        }
        if(c>0)
        {
            double avg = sum/c;
            return avg;
        }
        return 0;
    }
