    public static void main(String[] args) 
    {
        Scanner sc = new Scanner(System.in);
        MobileDetails[] mb = new MobileDetails[5];
        for (int i = 0; i < mb.length; i++) 
        {
            int a = sc.nextInt();sc.nextLine();
