        for(int i=0; i<d.length; i++)
        {
            if(d[i].pages%2!=0)
            {
                st = Arrays.copyOf(st,st.length+1);
                st[st.length-1]=d[i];
            }
        }
        for(int i =0; i<st.length; i++)
        {
            for(int j=i+1; j<st.length; j++)
            {
                if(st[i].getId()>st[j].getId())
                {
                    Document k=st[i];
                    st[i]=st[j];
                    st[j]=k;
                }
            }
        }
        if(st.length>0)
        {
            return st;
        }
        else
        {
            return null;
        }
    }
