    public double getAverageSalary(Employee[] e)
    {
        double sum = 0;
        for(int i=0; i<e.length; i++)
        {
            sum+=e[i].getSalary();
        }
        if(sum>0)
        {
            double avg = sum/e.length;
            return avg;
        }
        return 0;
    }

