    {
        Employee[] emp = new Employee[0];
        for (int i = 0; i < e.length; i++) {
            if(e[i].getDes().equalsIgnoreCase(d))
            {
                emp = Arrays.copyOf(emp,emp.length+1);
                emp[emp.length-1] = e[i];
            }
        }
        if(emp.length>0)
        {
            return emp;
        }
        return null;
    }
