        if(op == '+')
        {
            System.out.println(a+" "+op+" "+b+" = "+(a+b));
        }
        else if(op == '-')
        {
            System.out.println(a+" "+op+" "+b+" = "+(a-b));
        }
        else if(op == '*')
        {
            System.out.println(a+" "+op+" "+b+" = "+(a*b));
        }
        else if(op == '/')
        {
