/*
Find missing number

Input : 1 2 4 8 9 11 12 14
Output : 3 5 6 7 10 13
*/
import java.util.*;
public class Missing {
    public static void main(String[] args) {
        Scanner scan=new Scanner(System.in);
        int n=scan.nextInt();
        int[] arr=new int[n];
        for(int i=0;i<n;i++){
            arr[i]=scan.nextInt();
        }
        Arrays.sort(arr);
        ArrayList<Integer> missingNumber=new ArrayList<>();
        for(int i=0;i< arr.length-1;i++){
            int current=arr[i];
            int next=arr[i+1];
            while(current+1<next){
                missingNumber.add(current+1);
                current++;
            }
        }
        System.out.println(missingNumber.toString());
    }
}

/*
Question 1 - Multiple of 3

Write main method in Solution class.

In the main method , read an Integer (containing only numeric digits without decimal and
special characters) and check whether the sum of its digits is in multiple of 3.

If the given input is in multiple of 3, then print TRUE (as a String) else print FALSE(as a String).


For example: if the given value is 333, 3+3+3 is 9. which is multiple of 3, hence TRUE has to
printed.


Sample Input1:
333

Output:
TRUE


Sample Input2:
200

Output:
FALSE
 */
import java.util.*;
public class Multiple_of_3 {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int num = scan.nextInt();
        int sum = 0;
        while (num > 0) {
            int digit = num % 10;
            sum += digit;
            num /= 10;
        }
        if (sum % 3 == 0) {
            System.out.println("TRUE");
        } else {
            System.out.println("FALSE");
        }
    }
}

/*
Find the occurance of each character in a string
Input: Hello world
Output:
 H: 1
 e: 1
 l: 3
 o: 2
 w: 1
 r: 1
 d: 1
*/

import java.util.*;
public class Occurance {
    public static void main(String[] args) {
        Scanner scan=new Scanner(System.in);
        String str=scan.nextLine().replace(" ","");
        HashMap<Character,Integer> hashMap=new HashMap<>();
        for(int i=0;i<str.length();i++){
            char ch=str.charAt(i);
            if (hashMap.containsKey(ch)) {
                hashMap.put(ch, hashMap.get(ch) + 1);
            } else {
                hashMap.put(ch, 1);
            }
        }
        for(Map.Entry<Character,Integer> entry: hashMap.entrySet()){
            System.out.println(entry.getKey()+": "+entry.getValue());
        }
    }
}

/*
Take a number. If it odd then reverse it, otherwise print "Can not reverse"
Input : 123
Output : 321
Input : 234
Output : Can not reverse
 */
import java.util.*;
public class Odd_Reverse {
    public static void main(String[] args) {
        Scanner scan=new Scanner(System.in);
        int num=scan.nextInt();
        if(num%2!=0){
            int rev=0;
            while(num>0){
                int digit=num%10;
                rev=rev*10+digit;
                num/=10;
            }
            System.out.println(rev);
        }
        else{
            System.out.println("Cannot Reverse");
        }
    }
}

