public class UniqueNum {
    public static boolean isUnique(int n) {
        for (int i = 0; i <= 9; i++) {
            int ct = 0;
            for (int j = n; j != 0; j /= 10) {
                if (j % 10 == i)
                    ct++;
            }
            if (ct >= 2)
                return false;
        }   
        return true;
    }

    public static void main(String[] args) {
        int n = new java.util.Scanner(System.in).nextInt();
        boolean isUnique = true;
