    public static char[][] updateOnRule(char[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        char[][] updated = new char[m][n];

        for (int i = 0; i < m; i++) {
            int dot = 0;
            int hash = 0;
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == '.')
                    dot++;
                else if (matrix[i][j] == '#')
                    hash++;
                else {
                    updated[i][j] = matrix[i][j];
                    int k = j - 1;
                    while (hash > 0) {
                        updated[i][k--] = '#';
                        hash--;
                    }
                    while (dot > 0) {
                        updated[i][k--] = '.';
                        dot--;
                    }
                }
            }
            int k = n - 1;
            while (hash > 0) {
                updated[i][k--] = '#';
                hash--;
            }
            while (dot > 0) {
                updated[i][k--] = '.';
                dot--;
            }
        }
        return updated;
    }
}

