package Topics.LoopExamples;
// package LoopExamples;

import java.util.Scanner;

public class Squrt {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        for (int i = 1; i <= 10; i++) {
            System.out.print("Enter a number: ");
            double number = scanner.nextDouble();

            if (number < 0) {
                System.out.println("Square root of negative number is not real.");
            } else {
                double guess = number / 2; // initial guess
                double epsilon = 0.000001; // precision

                while (true) {
                    double newGuess = (guess + number / guess) / 2;
                    System.out.println("Current guess: " + newGuess);
                    if (Math.abs(newGuess - guess) < epsilon) {
                        break;
                    }

                    guess = newGuess;
                }

                System.out.println("Square root of " + number + " is: " + guess);
            }
        }
        scanner.close();
    }
}

package Topics.LoopExamples;

public class StrongNum {

    public static void main(String[] args) {
        int num = new java.util.Scanner(System.in).nextInt();

        int sum = 0;
        for (int i = num, temp = num; i > 0; i /= 10) {
            int fact = 1;
            int last = temp % 10;
            while (last > 1) {
                fact *= last;
                last--;
            }
            sum += fact;
            temp /= 10;
        }
        if (sum == num) {
            System.out.println(num + " is a Strong Number");
        } else {
            System.out.println(num + " is not a Strong Number");
        }
    }
}

package Topics.LoopExamples;

public class PronicNum {
    public static void main(String[] args) {
        int num = new java.util.Scanner(System.in).nextInt();
        int product = 0;
        for (int i = 1; i <= num; i++) {
            product = i * (i + 1);
            if (product == num) {
                System.out.println(num + " is a pronic number.");
                break;
            } else if (product > num) {
                System.out.println(num + " is not a pronic number.");
                break;
            }
        }
    }
}

