package Topics.LoopExamples;

public class HCF {
    public static void main(String[] args) {
        int num1 = new java.util.Scanner(System.in).nextInt();
        int num2 = new java.util.Scanner(System.in).nextInt();
        int small = (num1 < num2) ? num1 : num2;

        for (int i = small; i >= 1; i--) {
            if (num1 % i == 0 && num2 % i == 0) {
                System.out.println("HCF of " + num1 + " and " + num2 + " is: " + i);
                break;
            }
        }
    }
}

package Topics.LoopExamples;

public class LMC {
    public static void main(String[] args) {
        int num1 = new java.util.Scanner(System.in).nextInt();
        int num2 = new java.util.Scanner(System.in).nextInt();
        int large = (num1 > num2) ? num1 : num2;
        int i = 1;
        while (true) {
            if ((large * i) % num1 == 0 && (large * i) % num2 == 0) {
                System.out.println("LMC of " + num1 + " and " + num2 + " is: " + (large * i));
                break;
            }
            i++;
        }
    }
}

package Topics.LoopExamples;

public class DisariumNum {

    public static void main(String[] args) {
        int num = new java.util.Scanner(System.in).nextInt();
        int sum = 0;
        int count = 0;

        for (int i = num; i > 0; i /= 10) {
            count++;
        }

        for (int i = num; i > 0; i /= 10) {
            int last = i % 10;
            int prod = 1;
            int countCopy = count;
            while (countCopy > 0) {
                prod *= last;
                countCopy--;
            }
            sum += prod;
            count--;
        }

        if (sum == num) {
            System.out.println(num + " is a Disarium Number");
        } else {
            System.out.println(num + " is not a Disarium Number");
        }
    }
}

package Topics.LoopExamples;

public class ArmstrongNum {

    public static void main(String[] args) {
        int num = new java.util.Scanner(System.in).nextInt();
        int sum = 0;
        int count = 0;
        for (int i = num, temp = num; i > 0; i /= 10) {
            count++;
            temp /= 10;
        }
        for (int i = num, temp = num; i > 0; i /= 10) {
            int last = temp % 10;
            for (int j = 1; j < count; j++) {
                last *= temp % 10;
            }
            sum += last;
            temp /= 10;
        }
        if (sum == num) {
            System.out.println(num + " is an Armstrong Number");
        } else {
            System.out.println(num + " is not an Armstrong Number");
        }
    }
}

