        int temp = n;
        for (int i = count; i > 0; i--) {
            int d = temp % 10;
            int power = 1;
            for (int j = 0; j < i; j++) {
                power *= d;
            }
            sum += power;
            temp /= 10;
        }
        return sum == n;
    }
