import { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate, useParams } from "react-router-dom";
import { toast } from "react-toastify";

const EditUser = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const [formData, setFormData] = useState({ name: "", mobile: "", address: "", image: "" });
    const [loading, setLoading] = useState(true);
    const [image, setImage] = useState(null);

    useEffect(() => {
        axios.get(`http://localhost:3000/allUsers/${id}`)
            .then(({ data }) => setFormData({
                name: data.name ?? "",
                mobile: data.mobile ?? "",
                address: data.address ?? "",
                image: data.image ?? ""
            }))
            .catch(() => toast.error("Unable to load user"))
            .finally(() => setLoading(false));
    }, []);

    const handleChange = (event) => {
        setFormData({ ...formData, [event.target.name]: event.target.value });
    };

    const targetImage = (event) => {
        const x = event.target.files[0];
        const reader = new FileReader();
        reader.readAsDataURL(x);
        reader.onload = (ele) => {
            setImage(ele.target.result);
        };
    };

    const handleRemoveImage = () => {
        setImage(null);
    };

    const handleSubmit = (event) => {
        event.preventDefault();
        const updatedData = { ...formData, ...(image && { image }) };
        axios.put(`http://localhost:3000/allUsers/${id}`, updatedData)
            .then(() => {
                toast.success("User updated successfully");
                navigate("/");
            })
            .catch(() => toast.error("Unable to update user"));
    };


   
    return(
        <form onSubmit={handleSubmit}>

            <label htmlFor="name">Name</label>  
            <input type="text" id="name" name="name" value={formData.name} onChange={handleChange} placeholder="Enter Name" required/>
            <br/>
            <br/>
            <label htmlFor="mobile">Mobile</label>
            <input type="tel" id="mobile" name="mobile" value={formData.mobile} onChange={handleChange} placeholder="Enter Mobile" required/>
            <br/>
            <br/>
            <label htmlFor="address">Address</label>
            <input type="text" id="address" name="address" value={formData.address} onChange={handleChange} placeholder="Enter Address" required/>
            <br/>
            <br/>
            <label htmlFor="image">Image</label>
            <input type="file" id="image" name="image" onChange={targetImage} />
            {(image || formData.image) && (
                <div style={{ marginTop: '10px' }}>
                    <img 
                        src={image || formData.image} 
                        alt="Preview" 
                        style={{ width: '100px', height: '100px', objectFit: 'cover' }} 
                    />
                    {image && (
                        <button type="button" onClick={handleRemoveImage} style={{ marginLeft: '10px' }}>
                            Remove New Image
                        </button>
                    )}
                </div>
            )}
            <br />
            <br />
            <button type="submit" disabled={loading}>{loading ? "Loading..." : "Update"}</button>
        
        </form>
    )
}

export default EditUser;

import axios from "axios"
import { useEffect, useState } from "react"
import { Link } from "react-router-dom"
import { toast } from "react-toastify"
import DeleteUser from "./DeleteUser"

const Home = ()=>{

    let [userData, setUserData]= useState([])
    
    useEffect(()=>{
        axios.get("http://localhost:3000/allUsers").then((res)=>{
            console.log(res.data);
            setUserData(res.data)
        }).catch(() => {
          toast.error("Unable to load users")
        })
    },[])

      const removeDeletedUser = (id) => {
        setUserData((users) => users.filter((user) => user.id !== id))
      }

  return(
    <div>
        <button>
            <Link to={"/addUser"}>New User</Link>
        </button>

      <table border={1} style={{
        borderCollapse:"collapse",
        width:"100%"
      }}>
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Mobile</th>
                <th>Address</th>
                <th>Image</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            {userData.map((ele, index)=>(
                <tr key={index}>
                    <td>{ele.id}</td>
                     <td>{ele.name}</td>
                      <td>{ele.mobile}</td>
                       <td>{ele.address}</td>
                       <td>
                         {ele.image ? (
                           <img src={ele.image} alt={ele.name} style={{ width: '50px', height: '50px', objectFit: 'cover' }} />
                         ) : (
                           <span>No Image</span>
                         )}
                       </td>
                       <td>
                         <button>
                            <Link to={`/editUser/${ele.id}`}>Edit</Link>
                         </button>
                         <DeleteUser userId={ele.id} onDeleted={removeDeletedUser} />
                       </td>
                </tr>
            ))}
        </tbody>

      </table>
    </div>
  )
}
export default Home

import { useState } from 'react';
import axios from 'axios';
import { toast } from 'react-toastify'; 
import { useNavigate } from 'react-router-dom';

const AddUser = () => {
  const [name, setName] = useState('');
  const [mobile, setMobile] = useState('');
  const [address, setAddress] = useState('');
  const [image, setImage] = useState(null);
  const navigate = useNavigate();


  const handleSubmit = (e) => {
    e.preventDefault();
    
    const newUser = {
      name,
      mobile,
      address,
      image
    };

    axios.post('http://localhost:3000/allUsers', newUser)
      .then(() => {
        // console.log('User added successfully');
        toast.success('User added successfully', {
          position: "top-right",
        });
        navigate('/');
      })
      .catch((error) => {
        console.error('Error adding user:', error);
      });
  };

  let targetImage = (event) => {
    console.log(event.target.files[0]);
    let x = event.target.files[0];
    let reader = new FileReader();

    reader.readAsDataURL(x);

    reader.onload = (ele) => {
      console.log(reader.result);

      setImage(ele.target.result);
    }
  }

  const handleRemoveImage = () => {
    setImage(null);
  }

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label htmlFor="name">Name:</label>
        <input
          type="text"
          id="name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          required
        />
      </div>
      <div>
        <label htmlFor="mobile">Mobile:</label>
        <input
          type="tel"
          id="mobile"
          value={mobile}
          onChange={(e) => setMobile(e.target.value)}
          required
        />
      </div>
      <div>
        <label htmlFor="address">Address:</label>
        <input
          type="text"
          id="address"
          value={address}
          onChange={(e) => setAddress(e.target.value)}
          required
        />
      </div>
      <div>
        <label htmlFor="image">Image:</label>
        <input
          type="file"
          id="image"
          name="image"
          onChange={targetImage}
        />
        {image && (
          <div style={{ marginTop: '10px' }}>
            <img src={image} alt="Preview" style={{ width: '100px', height: '100px', objectFit: 'cover' }} />
            <button type="button" onClick={handleRemoveImage} style={{ marginLeft: '10px' }}>
              Remove Image
            </button>
          </div>
        )}
      </div>
      <button type="submit">Add User</button>
    </form>
  );
};

export default AddUser;

