        0 25px 60px rgba(0, 0, 0, 0.25);
}

#leftside {
    width: 55%;
    height: 100%;

    padding: 40px 50px;

    background: #f5f7fb;

    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

#header {
