    font-size: 1rem;

    line-height: 1.7;

    max-width: 520px;

    color: #3b4f53;
}

#appointbox {
    margin-top: 20px;

    background: white;

    padding: 35px;

    border-radius: 20px;

    border: 2px solid #2f6167;

    display: flex;
    flex-direction: column;

    gap: 25px;

    box-shadow:
        0 10px 30px rgba(0, 0, 0, 0.08);
}

#appointtitle {
    font-size: 32px;

    font-weight: 700;

    color: #174851;
}

#inputs {
    display: flex;
    align-items: center;

    gap: 15px;
}

.inputbox {
    flex: 1;

    height: 65px;

    border: 2px solid #e6e6e6;

    border-radius: 12px;

    display: flex;
    align-items: center;
    justify-content: space-between;

    padding: 0 18px;

    background: #fafafa;

    position: relative;

    transition: 0.3s;
}

.inputbox:hover {
    border-color: #c9c9c9;
}

.inputbox:focus-within {
    border-color: #2f6167;

    background: white;
}

.inputbox input,
.inputbox select {
    width: 100%;

    border: none;
    outline: none;

    background: transparent;

    font-size: 15px;

    color: #444;
}

.inputbox select {
    appearance: none;
    -webkit-appearance: none;
    -moz-appearance: none;

    cursor: pointer;
}

.inputbox input[type="date"] {
    cursor: pointer;
}

.inputbox input[type="date"]::-webkit-calendar-picker-indicator {
    opacity: 0;

    position: absolute;

    width: 100%;

    left: 0;

    cursor: pointer;
}

.inputbox i {
    color: #999;

    font-size: 16px;

    margin-left: 10px;

    pointer-events: none;
}

#searchbtn {
    height: 65px;

    padding: 0 35px;

    border: none;

    border-radius: 12px;

    background: #b779d7;

    color: white;

    font-size: 16px;
    font-weight: 600;

    cursor: pointer;

    transition: 0.3s;
}

#searchbtn:hover {
    background: #9d5dc0;

    transform: translateY(-2px);
}

#rightside {
