}



/* --- Fixed Keyframes --- */
@keyframes torotate {

    /* Highly recommended to define 'from' for smoother tracking on hover */
    from {
        background-color: aqua;
        transform: rotate(0deg);
    }

    to {
        background-color: blue;
        transform: rotate(360deg);
    }
}

@keyframes toscale {
    to {
        transform: scale(2);
    }
}

@keyframes toskew {
    to {
        transform: skew(30deg);
    }
}

@keyframes totranslate {
    to {
        transform: translate(200px);
        /* Fixed: Changed 'deg' to 'px' */
    }
}   

/* 1. When #btn1 inside .transform is hovered, animate the #object */
.transform:has(#btn1:hover) #object {
    animation: torotate 2s ease forwards infinite;
    
}

/* 2. When #btn2 inside .transform is hovered, animate the #object */
.transform:has(#btn2:hover) #object {
    animation: toscale 1s ease forwards;
}

/* 3. When #btn3 inside .transform is hovered, animate the #object */
.transform:has(#btn3:hover) #object {
    animation: toskew 1s ease forwards;
}

/* 4. When #btn4 inside .transform is hovered, animate the #object */
.transform:has(#btn4:hover) #object {
    animation: totranslate 1s ease forwards;
}
